<?php defined('BASEPATH') OR exit('No direct script access allowed');class Talk extends MY_Controller{private $c;function __construct(){parent::__construct();$this->c=$this->require_auth();if(!$this->c)return;$this->load->model('Talk_model','talk');}function channels(){if($this->input->method(TRUE)==='POST'){$d=$this->body();if(trim($d['name']??'')==='')return $this->fail('VALIDATION_ERROR','Channel name required',422);return $this->respond($this->talk->create_channel($this->c['sub'],$this->c['organizationId'],$d),201);}$p=max(1,(int)$this->input->get('page'));$pp=min(100,max(1,(int)($this->input->get('perPage')?:20)));return $this->respond($this->talk->channels($this->c['sub'],$this->c['organizationId'],trim((string)$this->input->get('q')),$this->input->get('type'),$p,$pp));}function channel($id){$m=$this->input->method(TRUE);if($m==='GET')$r=$this->talk->get_channel($id,$this->c['sub'],$this->c['organizationId']);elseif($m==='PATCH')$r=$this->talk->update_channel($id,$this->c['sub'],$this->c['organizationId'],$this->body());else{$r=$this->talk->archive($id,$this->c['sub'],$this->c['organizationId']);if($r)return $this->respond(array());}return $r?$this->respond($r):$this->fail('NOT_FOUND','Channel not found',404);}function members($id){$d=$this->body();$r=$this->talk->add_members($id,$this->c['sub'],$this->c['organizationId'],$d['userIds']??array(),$d['agentIds']??array());return $r?$this->respond(array()):$this->fail('NOT_FOUND','Channel not found',404);}function member($id,$mid){return $this->talk->remove_member($id,$mid,$this->c['sub'],$this->c['organizationId'])?$this->respond(array()):$this->fail('NOT_FOUND','Member not found',404);}function messages($id){if($this->input->method(TRUE)==='POST'){$d=$this->body();if(trim($d['content']??'')==='')return $this->fail('VALIDATION_ERROR','Content required',422);$this->db->trans_begin();$r=$this->talk->send($id,$this->c['sub'],$this->c['organizationId'],$d);if(!$r){$this->db->trans_rollback();return $this->fail('NOT_FOUND','Channel not found',404);}$this->load->model('Attachment_model','attachments');list($ok,$err)=$this->attachments->claim_talk($d['attachmentIds']??array(),$this->c['organizationId'],$this->c['sub'],$r['id']);if(!$ok){$this->db->trans_rollback();return $this->fail('VALIDATION_ERROR',$err,422);}$this->db->trans_commit();$this->load->library('Webhook_dispatcher');$this->webhook_dispatcher->dispatch($this->c['organizationId'],'message.created',array('channelId'=>$id,'messageId'=>$r['id']));return $this->respond($r,201);}$p=max(1,(int)$this->input->get('page'));$pp=min(100,max(1,(int)($this->input->get('perPage')?:20)));$r=$this->talk->messages($id,$this->c['sub'],$this->c['organizationId'],$p,$pp,$this->input->get('threadParentId'));return $r?$this->respond($r):$this->fail('NOT_FOUND','Channel not found',404);}function agents(){$rows=$this->db->select('id,name,role,emoji,color,is_built_in')->where('organization_id',$this->c['organizationId'])->order_by('name')->get('agents')->result_array();$r=array_map(function($a){return array('id'=>$a['id'],'name'=>$a['name'],'role'=>$a['role'],'emoji'=>$a['emoji'],'color'=>$a['color'],'isBuiltIn'=>(bool)$a['is_built_in']);},$rows);return $this->respond($r);}function message($id){$m=$this->input->method(TRUE);if($m==='GET')$r=$this->talk->message($id,$this->c['sub'],$this->c['organizationId']);elseif($m==='PATCH'){$content=trim($this->body()['content']??'');if($content==='')return $this->fail('VALIDATION_ERROR','Content required',422);$r=$this->talk->edit_message($id,$this->c['sub'],$this->c['organizationId'],$content);}else{if($this->talk->delete_message($id,$this->c['sub'],$this->c['organizationId']))return $this->respond(array());$r=NULL;}return $r?$this->respond($r):$this->fail('NOT_FOUND','Message not found or operation not permitted',404);}function reaction($id){$emoji=trim($this->body()['emoji']??'');if($emoji===''||mb_strlen($emoji)>16)return $this->fail('VALIDATION_ERROR','Invalid emoji',422);$r=$this->talk->reaction($i